	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/entries/{entryId}/submission", wrapper.CreateSubmission)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/entries/{entryId}/submission/ack", wrapper.AckSubmissionResolution)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tags", wrapper.ListTags)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tags", wrapper.CreateTag)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/tags/{tagId}", wrapper.DeleteTag)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/tags/{tagId}", wrapper.RenameTag)
